<?php $items=$bulletins??[];?>
<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><strong>Publicaciones vigentes</strong><small class="d-block text-body-secondary">Estas publicaciones aparecen realmente en Property App.</small></div><div class="card-body bulletin-list"><?php foreach($items as $post):?><article><div class="bulletin-icon"><i class="bi bi-megaphone"></i></div><div><div class="d-flex gap-2 align-items-center"><h5><?=e($post['title'])?></h5><?php if(!empty($post['is_pinned'])):?><span class="badge text-bg-warning">Fijada</span><?php endif;?></div><p><?=nl2br(e($post['body']))?></p><small><?=e($post['author']??'Administración')?> · <?=e(format_datetime_es((string)($post['published_at']?:$post['created_at'])))?> · Audiencia: <?=e($post['audience_type'])?></small></div></article><?php endforeach;?><?php if(!$items):?><div class="text-center text-body-secondary py-4">Cartelera vacía.</div><?php endif;?></div></div></div><?php if(can('bulletin.manage')):?><div class="col-xl-5"><div class="card"><div class="card-header"><strong>Nueva publicación</strong></div><div class="card-body"><form method="post" action="<?=url('create-bulletin')?>"><?=csrf_field()?><div class="mb-3"><label class="form-label">Título</label><input class="form-control" name="title" required></div><div class="mb-3"><label class="form-label">Contenido</label><textarea class="form-control" rows="5" name="body" required></textarea></div><div class="row g-3"><div class="col-6"><label class="form-label">Categoría</label><select class="form-select" name="category"><option value="general">General</option><option value="services">Servicios</option><option value="maintenance">Mantenimiento</option><option value="security">Seguridad</option><option value="emergency">Emergencia</option></select></div><div class="col-6"><label class="form-label">Audiencia</label><select class="form-select" name="audience"><option value="all">Todos</option><option value="residents">Residentes</option><option value="commercial">Locales / oficinas</option></select></div><div class="col-6"><label class="form-label">Vence</label><input type="date" class="form-control" name="expires_at"></div><div class="col-6 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="pinned" value="1"><span class="form-check-label">Fijar publicación</span></label></div></div><button class="btn btn-primary w-100 mt-3">Publicar en Property App</button></form></div></div></div><?php endif;?></div>
